const body = $json.body || $json || {};

const clean = (value) => String(value ?? '').trim();

const isUuid = (value) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    clean(value)
  );

const usuario_id = clean(body.usuario_id);

if (!isUuid(usuario_id)) {
  throw new Error('Worker recibió usuario_id inválido.');
}

const conversacion_id = clean(body.conversacion_id);

if (!conversacion_id) {
  throw new Error('Worker recibió conversacion_id vacío.');
}

const mensaje = clean(body.mensaje);

if (!mensaje) {
  throw new Error('Worker recibió mensaje vacío.');
}

const accionesPermitidas = new Set([
  'GENERAR_EXCEL',
  'GENERAR_PDF',
  'GENERAR_WORD',
  'CREAR_TAREA',
  'CREAR_OBJETIVO',
  'GUARDAR_MEMORIA',
  'VER_DASHBOARD',
  'VER_BRIEFING'
]);

const acciones = Array.isArray(body.acciones)
  ? body.acciones
      .map((accion, index) => ({
        id: clean(accion?.id || `accion-${index + 1}`),
        tipo: clean(accion?.tipo).toUpperCase(),
        datos:
          accion?.datos &&
          typeof accion.datos === 'object' &&
          !Array.isArray(accion.datos)
            ? accion.datos
            : {}
      }))
      .filter((accion) => accionesPermitidas.has(accion.tipo))
  : [];

return [
  {
    json: {
      usuario_id,
      usuario_id_original: clean(
        body.usuario_id_original || usuario_id
      ),
      usuario_key: clean(body.usuario_key || usuario_id),
      conversacion_id,
      request_id: isUuid(body.request_id) ? clean(body.request_id) : '',
      operacion:
        clean(body.operacion).toLowerCase() === 'regenerar'
          ? 'regenerar'
          : 'mensaje',
      mensaje_id: isUuid(body.mensaje_id) ? clean(body.mensaje_id) : '',
      nombre: clean(body.nombre || 'Usuario'),
      mensaje,
      plan: clean(body.plan || 'free'),
      origen: clean(body.origen || 'eos-web'),

      historial: Array.isArray(body.historial)
        ? body.historial.slice(-10)
        : [],

      respuesta_gateway: clean(body.respuesta_gateway),

      acciones,
      requiere_worker:
        body.requiere_worker === true || acciones.length > 0,

      metadata:
        body.metadata &&
        typeof body.metadata === 'object' &&
        !Array.isArray(body.metadata)
          ? body.metadata
          : {},

      job_id: clean(
        body.job_id || `${conversacion_id}-${Date.now()}`
      ),

      received_at: clean(
        body.received_at || new Date().toISOString()
      ),

      worker_received_at: new Date().toISOString()
    }
  }
];

const base = $('01 WK Preparar Entrada').first().json || {};
const decision = {};

function rows(name) {
  try {
    return $(name).all().map(i => i.json || {}).filter(x => x && Object.keys(x).length > 0);
  } catch (e) { return []; }
}
function first(name) { return rows(name)[0] || {}; }
function line(v) { return String(v || '').trim(); }

const perfil = first('60 WK Leer Perfil');
const proyecto = first('61 WK Leer Proyecto Activo');
const memorias = rows('64 WK Leer Memorias');
const objetivos = rows('62 WK Leer Objetivos').filter(o => ['activo', 'pausado'].includes(o.estado));
const tareas = rows('63 WK Leer Tareas');
const conversaciones = rows('65 WK Leer Conversaciones');

const contexto_maestro = `
USUARIO
Nombre: ${base.nombre || perfil.nombre_visible || 'Usuario'}
Usuario ID: ${base.usuario_id}
Plan: ${base.plan || 'free'}
Origen: ${base.origen || 'eos-web'}

PERFIL
${perfil.id ? JSON.stringify(perfil, null, 2) : 'Perfil base sin datos avanzados todavía.'}

PROYECTO ACTIVO
${proyecto.id ? JSON.stringify(proyecto, null, 2) : 'No hay proyecto activo registrado.'}

MEMORIAS RELEVANTES
${memorias.map(m => `- [${line(m.clave || m.categoria || 'general')}] ${line(m.titulo || 'Dato')}: ${line(m.contenido || m.texto || m.memoria)}`).join('\n') || '- Sin memorias guardadas.'}

OBJETIVOS
${objetivos.map(o => `- ID ${line(o.id)} | ${line(o.titulo || o.nombre || 'Objetivo')} | estado ${line(o.estado)} | progreso ${Number(o.progreso || 0)}% | medición ${line(o.tipo_medicion || 'porcentaje')} | actual ${line(o.valor_actual)} ${line(o.unidad)} | meta ${line(o.valor_objetivo)} ${line(o.unidad)} | próximo paso ${line(o.proximo_paso || 'sin definir')}`).join('\n') || '- Sin objetivos activos o pausados.'}

TAREAS
${tareas.map(t => `- ${line(t.titulo || t.nombre || 'Tarea')}: ${line(t.estado || t.descripcion || '')}`).join('\n') || '- Sin tareas registradas.'}

CONVERSACIONES RECIENTES
${conversaciones.map(c => `- ${line(c.titulo || c.resumen || c.id || 'Conversación')}`).join('\n') || '- Sin conversaciones previas.'}

MENSAJE ACTUAL
${base.mensaje || decision.mensaje || ''}
`.trim();

return [{ json: { ...base, ...decision, perfil, proyecto_activo: proyecto, memorias, objetivos, tareas, conversaciones, contexto_maestro } }];

const i = $input.first().json || {};

const normalizar = (valor) =>
  String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const mensaje = normalizar(i.mensaje);
const accionesGateway = Array.isArray(i.acciones) ? i.acciones : [];
const accionesObjetivo = new Set([
  'CREAR_OBJETIVO',
  'ACTUALIZAR_PROGRESO',
  'REGISTRAR_EVIDENCIA',
  'COMPLETAR_HITO',
  'PAUSAR_OBJETIVO',
  'REANUDAR_OBJETIVO',
]);

const principalGateway = accionesGateway.find((item) => {
  const tipo = String(item?.tipo || '').trim().toUpperCase();
  return tipo && tipo !== 'GUARDAR_MEMORIA' && !accionesObjetivo.has(tipo);
});

let accion = String(principalGateway?.tipo || '').trim().toUpperCase();

if (!accion) {
  const verboArchivo =
    /\b(genera|generar|crea|crear|prepara|preparar|hace|hacer|pasa|pasame|pasamelo|envia|enviame|manda|mandame|dame|descarga|descargar)\b/;
  const niegaArchivo =
    /\b(no me mandes|no mandes|no quiero archivo|sin archivo|solo responde|solo contestame|solo saludame|saludame)\b/.test(mensaje);

  if (niegaArchivo) accion = 'RESPONDER';
  else if (verboArchivo.test(mensaje) && /\b(excel|xlsx|planilla|hoja de calculo)\b/.test(mensaje)) accion = 'GENERAR_EXCEL';
  else if (verboArchivo.test(mensaje) && /\bpdf\b/.test(mensaje)) accion = 'GENERAR_PDF';
  else if (verboArchivo.test(mensaje) && /\b(word|docx|documento de word)\b/.test(mensaje)) accion = 'GENERAR_WORD';
  else if (/\b(crea|crear|registra|registrar|agrega|agregar)\b.*\b(tarea|recordatorio|pendiente)\b/.test(mensaje)) accion = 'CREAR_TAREA';
  else if (/\b(dashboard|metricas|indicadores|tablero)\b/.test(mensaje)) accion = 'VER_DASHBOARD';
  else if (/\b(briefing|resumen ejecutivo|resumen diario)\b/.test(mensaje)) accion = 'VER_BRIEFING';
  else accion = 'RESPONDER';
}

const esArchivo = ['GENERAR_EXCEL', 'GENERAR_PDF', 'GENERAR_WORD'].includes(accion);

return [{
  json: {
    ...i,
    accion_principal: accion,
    accion_eos: accion,
    accion,
    datos_accion: principalGateway?.datos || {},
    requiere_archivo: esArchivo,
    archivo_tipo:
      accion === 'GENERAR_EXCEL' ? 'excel' :
      accion === 'GENERAR_PDF' ? 'pdf' :
      accion === 'GENERAR_WORD' ? 'word' : '',
    cantidad_acciones_objetivo: accionesGateway.filter((item) =>
      accionesObjetivo.has(String(item?.tipo || '').trim().toUpperCase())
    ).length,
    parser_version: 'eos-router-v7-objectives-commands',
  },
}];

const i = $input.first().json || {};
const datos = i.datos_accion || i.accion_datos || {};

const normalizar = (texto) =>
  String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const textoCompleto = [
  i.mensaje,
  datos.tema,
  datos.tipo,
  datos.rubro,
  datos.negocio,
  datos.descripcion
]
  .filter(Boolean)
  .join(' ')
  .toLowerCase();

let plantilla = 'business';
let rubro = datos.rubro || 'negocio_general';

if (/finanzas personales|deuda|deudas|ahorro|presupuesto personal|salir de deudas/.test(textoCompleto)) {
  plantilla = 'personal';
  rubro = 'persona_fisica';
}

if (/restaurante|gastronomia|comida|hamburg|pizza|cafeteria|bar/.test(textoCompleto)) {
  plantilla = 'business';
  rubro = 'gastronomia';
}

const nombreBase = datos.negocio || datos.nombre || i.nombre || 'usuario';
const nombreArchivo = plantilla === 'personal'
  ? `plan_financiero_eos_${normalizar(nombreBase)}`
  : `control_negocio_eos_${normalizar(nombreBase)}`;
const dominio = 'https://transtech-gl3zn6y07-trans-tech.vercel.app';
const url = `${dominio}/descargar` +
  `?tipo=excel` +
  `&plantilla=${encodeURIComponent(plantilla)}` +
  `&nombre=${encodeURIComponent(nombreArchivo)}` +
  `&rubro=${encodeURIComponent(rubro)}` +
  `&negocio=${encodeURIComponent(nombreBase)}` +
  `&tema=${encodeURIComponent(datos.tema || i.mensaje || 'control general')}`;

return [{ json: {
  ...i,
  ok: true,
  tipo: 'archivo',
  accion: 'GENERAR_EXCEL',
  archivo_tipo: 'excel',
  archivo_url: url,
  respuesta: `Tu Excel ya está listo.\n\nDescargar archivo: ${url}`
} }];

const i = $input.first().json || {};
return [{ json: {
  ...i,
  ok: false,
  execution_status: 'no_disponible',
  tipo: 'texto',
  archivo_tipo: 'pdf',
  archivo_url: '',
  respuesta: 'Puedo preparar la estructura del PDF, pero el generador PDF todavía debe conectarse. La solicitud quedó registrada como no disponible; no como una ejecución exitosa.'
} }];

const i = $input.first().json || {};
return [{ json: {
  ...i,
  ok: false,
  execution_status: 'no_disponible',
  tipo: 'texto',
  archivo_tipo: 'word',
  archivo_url: '',
  respuesta: 'Puedo preparar la estructura del documento Word, pero el generador DOCX todavía debe conectarse. La solicitud quedó registrada como no disponible; no como una ejecución exitosa.'
} }];

const i = $input.first().json || {};
const datos = i.datos_accion || {};
const prioridades = { baja: 1, media: 3, alta: 4, critica: 5 };
const prioridadRecibida = Number(datos.prioridad ?? i.prioridad_eos);
const prioridadTexto = String(datos.prioridad || i.prioridad_eos || 'media').trim().toLowerCase();
const prioridad = Number.isFinite(prioridadRecibida)
  ? Math.max(1, Math.min(5, Math.round(prioridadRecibida)))
  : (prioridades[prioridadTexto] || 3);
const titulo = String(datos.titulo || datos.nombre || i.mensaje || 'Nueva tarea EOS').trim().slice(0, 120);
const descripcion = String(datos.descripcion || i.mensaje || titulo).trim().slice(0, 1200);
return [{ json: {
  ...i,
  titulo,
  descripcion,
  estado: 'pendiente',
  prioridad,
  created_at: new Date().toISOString()
} }];

const entrada = $input.first().json || {};
const memoria = entrada.memoria || entrada.decision?.memoria || null;
let contenido = '';
let titulo = 'Dato importante';
let categoria = 'general';

if (typeof memoria === 'string') contenido = memoria;
else if (memoria && typeof memoria === 'object') {
  contenido = memoria.contenido || memoria.texto || memoria.descripcion || '';
  titulo = memoria.titulo || titulo;
  categoria = memoria.categoria || categoria;
}
if (!contenido) contenido = String(entrada.mensaje || '').trim();

return [{ json: { ...entrada, usuario_id: entrada.usuario_id || $('01 WK Preparar Entrada').first().json.usuario_id, categoria, titulo, contenido, importancia: 5, origen: 'decision_engine', estado: 'activo', created_at: new Date().toISOString(), updated_at: new Date().toISOString() } }];

const entrada=$('21 WK Parsear Decisión').item.json; const metricas=$input.all().map(i=>i.json).filter(x=>x && Object.keys(x).length);
let lineas=metricas.map(m=>`- ${m.metric_label||m.metric_key||'Métrica'}: ${m.metric_value||m.metric_number||'sin valor'}`).join('\n');
if(!lineas) lineas='Todavía no hay métricas cargadas para este usuario.';
return [{json:{...entrada,tipo:'texto',respuesta:`Dashboard EOS:\n${lineas}`}}];

const entrada=$('21 WK Parsear Decisión').item.json; const b=$input.first().json||{};
const respuesta=b.resumen ? `Briefing EOS:
${b.resumen}

Prioridades:
1. ${b.prioridad_1||'Sin prioridad'}
2. ${b.prioridad_2||'Sin prioridad'}
3. ${b.prioridad_3||'Sin prioridad'}` : 'Todavía no hay briefing generado para este usuario.';
return [{json:{...entrada,tipo:'texto',respuesta}}];

const i = $input.first().json || {};
const base = $('02 WK Preparar Orden Confiable').first().json || {};
const accion = String(base.accion_principal || i.accion_principal || i.accion_eos || i.accion || 'RESPONDER')
  .trim()
  .toUpperCase();
const esArchivo = ['GENERAR_EXCEL', 'GENERAR_PDF', 'GENERAR_WORD'].includes(accion);
const archivoUrl = String(i.archivo_url || i.download_url || i.url || '').trim();
const respuestaEspecifica = String(i.respuesta || i.output || i.text || '').trim();
const respuestaGateway = String(base.respuesta_gateway || i.respuesta_gateway || i.respuesta_rapida || '').trim();
let respuesta = respuestaEspecifica || respuestaGateway;

if (esArchivo && archivoUrl) {
  respuesta = respuestaEspecifica || 'Tu archivo ya está listo.';
}
if (esArchivo && !archivoUrl) {
  respuesta = respuestaEspecifica || 'No pude completar el archivo en este momento.';
}
if (!esArchivo && !respuesta) respuesta = 'Decime qué necesitás y avanzamos.';

const noDisponible = i.execution_status === 'no_disponible' ||
  (['GENERAR_PDF', 'GENERAR_WORD'].includes(accion) && !archivoUrl);

return [{ json: {
  ...base,
  ...i,
  ok: i.ok !== false && !noDisponible,
  accion,
  accion_principal: accion,
  respuesta,
  tipo: esArchivo && archivoUrl ? 'archivo' : 'texto',
  archivo_url: esArchivo ? archivoUrl : '',
  archivo_tipo: esArchivo ? String(i.archivo_tipo || '').trim() : '',
  execution_status: noDisponible ? 'no_disponible' : 'completada',
  metadata: base.metadata || i.metadata || {}
} }];

const i = $input.first().json || {};
const acciones = Array.isArray(i.acciones) ? i.acciones : [];
let memorias = acciones
  .filter((accion) => String(accion?.tipo || '').trim().toUpperCase() === 'GUARDAR_MEMORIA')
  .slice(0, 5)
  .map((accion) => accion?.datos || {});

if (memorias.length === 0 && /\b(recuerda|recorda|guarda esto|memoriza)\b/i.test(String(i.mensaje || ''))) {
  memorias = [{
    clave: 'general.dato_importante',
    categoria: 'general',
    titulo: 'Dato importante',
    contenido: i.mensaje,
    importancia: 7,
    confianza: 1,
    confirmada: true,
  }];
}

const slug = (valor) =>
  String(valor || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9._-]+/g, '_')
    .replace(/^[_\-.]+|[_\-.]+$/g, '')
    .slice(0, 120);

const hash = (valor) => {
  let resultado = 2166136261;
  const texto = String(valor || '');
  for (let index = 0; index < texto.length; index += 1) {
    resultado ^= texto.charCodeAt(index);
    resultado = Math.imul(resultado, 16777619);
  }
  return (resultado >>> 0).toString(36);
};

return memorias.map((datos) => {
  const categoria = slug(datos.categoria || 'general') || 'general';
  const titulo = String(datos.titulo || datos.nombre || 'Dato importante').trim().slice(0, 160);
  const contenido = String(datos.contenido || datos.valor || datos.descripcion || i.mensaje || '').trim();
  const entidad = String(datos.entidad || '').trim().slice(0, 160);
  const claveBase = slug(datos.clave || datos.key || `${categoria}.${entidad || titulo}`);
  const clave = claveBase && !/dato_importante$/.test(claveBase)
    ? claveBase
    : `${categoria}.dato_${hash(contenido)}`;

  return {
    json: {
      ...i,
      clave,
      categoria,
      titulo,
      contenido,
      entidad,
      valor: datos.valor && typeof datos.valor === 'object'
        ? datos.valor
        : { contenido },
      importancia: Math.max(1, Math.min(10, Number(datos.importancia || 5))),
      confianza: Math.max(0, Math.min(1, Number(datos.confianza ?? 0.8))),
      confirmada: datos.confirmada === true,
      origen_memoria: 'gateway_structured_extraction',
      estado_memoria: 'activo',
      metadata_memoria: {
        request_id: i.request_id || '',
        operacion: i.operacion || 'mensaje',
        extractor_version: 'eos-memory-v1',
      },
    },
  };
}).filter((item) => item.json.contenido);

const i = $input.first().json || {};
const acciones = Array.isArray(i.acciones) ? i.acciones : [];
const objetivos = Array.isArray(i.objetivos) ? i.objetivos : [];
const tiposPermitidos = new Set([
  'CREAR_OBJETIVO',
  'ACTUALIZAR_PROGRESO',
  'REGISTRAR_EVIDENCIA',
  'COMPLETAR_HITO',
  'PAUSAR_OBJETIVO',
  'REANUDAR_OBJETIVO',
]);

const texto = (valor, maximo = 500) =>
  String(valor ?? '').trim().slice(0, maximo);

const numero = (valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  const resultado = Number(valor);
  return Number.isFinite(resultado) ? resultado : null;
};

const fecha = (valor) => {
  const resultado = texto(valor, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(resultado) ? resultado : null;
};

const slug = (valor) =>
  texto(valor, 120)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const esUuid = (valor) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(texto(valor));

const hashHex = (valor) => {
  let a = 0x811c9dc5;
  let b = 0x9e3779b9;
  for (const caracter of String(valor)) {
    const codigo = caracter.charCodeAt(0);
    a = Math.imul(a ^ codigo, 0x01000193) >>> 0;
    b = Math.imul(b ^ (codigo + a), 0x85ebca6b) >>> 0;
  }
  const parte = (numeroHash) => numeroHash.toString(16).padStart(8, '0');
  return (parte(a) + parte(b) + parte(a ^ b) + parte(Math.imul(a, b) >>> 0)).slice(0, 32);
};

const uuidDeterminista = (semilla) => {
  const hex = hashHex(semilla).split('');
  hex[12] = '4';
  hex[16] = ['8', '9', 'a', 'b'][parseInt(hex[16], 16) % 4];
  const valor = hex.join('');
  return `${valor.slice(0, 8)}-${valor.slice(8, 12)}-${valor.slice(12, 16)}-${valor.slice(16, 20)}-${valor.slice(20, 32)}`;
};

const porId = new Map(objetivos.filter((o) => esUuid(o.id)).map((o) => [o.id, o]));

return acciones
  .map((accion, indice) => {
    let tipo = texto(accion?.tipo, 60).toUpperCase();
    if (!tiposPermitidos.has(tipo)) return null;

    const datos = accion?.datos && typeof accion.datos === 'object' && !Array.isArray(accion.datos)
      ? accion.datos
      : {};

    let objetivoId = esUuid(datos.objetivo_id) && porId.has(datos.objetivo_id)
      ? datos.objetivo_id
      : '';

    if (!objetivoId && tipo !== 'CREAR_OBJETIVO') {
      const tituloBuscado = texto(datos.objetivo_titulo, 180).toLowerCase();
      const coincidencias = objetivos.filter((o) =>
        texto(o.titulo, 180).toLowerCase() === tituloBuscado
      );
      if (coincidencias.length === 1) objetivoId = coincidencias[0].id;
    }

    if (tipo !== 'CREAR_OBJETIVO' && !objetivoId) return null;

    const progreso = numero(datos.progreso);
    const valorActual = numero(datos.valor_actual);

    if (tipo === 'ACTUALIZAR_PROGRESO' && progreso === null && valorActual === null) {
      tipo = 'REGISTRAR_EVIDENCIA';
    }

    const hitos = Array.isArray(datos.hitos)
      ? datos.hitos.slice(0, 8).map((hito, orden) => {
          const titulo = texto(hito?.titulo, 180);
          return {
            clave: slug(hito?.clave || titulo || `hito_${orden + 1}`),
            titulo,
            descripcion: texto(hito?.descripcion, 500) || null,
            peso: Math.max(0.0001, numero(hito?.peso) ?? 1),
            orden: numero(hito?.orden) ?? orden,
            fecha_limite: fecha(hito?.fecha_limite),
          };
        }).filter((hito) => hito.titulo)
      : [];

    const payload = {
      titulo: texto(datos.titulo, 180) || null,
      descripcion: texto(datos.descripcion, 1200) || null,
      objetivo_titulo: texto(datos.objetivo_titulo, 180) || null,
      tipo_medicion: ['porcentaje', 'numerico', 'monetario', 'hitos'].includes(texto(datos.tipo_medicion).toLowerCase())
        ? texto(datos.tipo_medicion).toLowerCase()
        : null,
      valor_inicial: numero(datos.valor_inicial),
      valor_actual: valorActual,
