  let resultado = 2166136261;
  const texto = String(valor || '');
  for (let index = 0; index < texto.length; index += 1) {
    resultado ^= texto.charCodeAt(index);
    resultado = Math.imul(resultado, 16777619);
  }
  return (resultado >>> 0).toString(36);
};

return memorias.map((datos) => {
  const categoria = slug(datos.categoria || 'general') || 'general';
  const titulo = String(datos.titulo || datos.nombre || 'Dato importante').trim().slice(0, 160);
  const contenido = String(datos.contenido || datos.valor || datos.descripcion || i.mensaje || '').trim();
  const entidad = String(datos.entidad || '').trim().slice(0, 160);
  const claveBase = slug(datos.clave || datos.key || `${categoria}.${entidad || titulo}`);
  const clave = claveBase && !/dato_importante$/.test(claveBase)
    ? claveBase
    : `${categoria}.dato_${hash(contenido)}`;

  return {
    json: {
      ...i,
      clave,
      categoria,
      titulo,
      contenido,
      entidad,
      valor: datos.valor && typeof datos.valor === 'object'
        ? datos.valor
        : { contenido },
      importancia: Math.max(1, Math.min(10, Number(datos.importancia || 5))),
      confianza: Math.max(0, Math.min(1, Number(datos.confianza ?? 0.8))),
      confirmada: datos.confirmada === true,
      origen_memoria: 'gateway_structured_extraction',
      estado_memoria: 'activo',
      metadata_memoria: {
        request_id: i.request_id || '',
        operacion: i.operacion || 'mensaje',
        extractor_version: 'eos-memory-v1',
      },
    },
  };
}).filter((item) => item.json.contenido);

const i = $input.first().json || {};
const acciones = Array.isArray(i.acciones) ? i.acciones : [];
const objetivos = Array.isArray(i.objetivos) ? i.objetivos : [];
const tiposPermitidos = new Set([
  'CREAR_OBJETIVO',
  'ACTUALIZAR_PROGRESO',
  'REGISTRAR_EVIDENCIA',
  'COMPLETAR_HITO',
  'PAUSAR_OBJETIVO',
  'REANUDAR_OBJETIVO',
]);

const texto = (valor, maximo = 500) =>
  String(valor ?? '').trim().slice(0, maximo);

const numero = (valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  const resultado = Number(valor);
  return Number.isFinite(resultado) ? resultado : null;
};

const fecha = (valor) => {
  const resultado = texto(valor, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(resultado) ? resultado : null;
};

const slug = (valor) =>
  texto(valor, 120)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

const esUuid = (valor) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(texto(valor));

const hashHex = (valor) => {
  let a = 0x811c9dc5;
  let b = 0x9e3779b9;
  for (const caracter of String(valor)) {
    const codigo = caracter.charCodeAt(0);
    a = Math.imul(a ^ codigo, 0x01000193) >>> 0;
    b = Math.imul(b ^ (codigo + a), 0x85ebca6b) >>> 0;
  }
  const parte = (numeroHash) => numeroHash.toString(16).padStart(8, '0');
  return (parte(a) + parte(b) + parte(a ^ b) + parte(Math.imul(a, b) >>> 0)).slice(0, 32);
};

const uuidDeterminista = (semilla) => {
  const hex = hashHex(semilla).split('');
  hex[12] = '4';
  hex[16] = ['8', '9', 'a', 'b'][parseInt(hex[16], 16) % 4];
  const valor = hex.join('');
  return `${valor.slice(0, 8)}-${valor.slice(8, 12)}-${valor.slice(12, 16)}-${valor.slice(16, 20)}-${valor.slice(20, 32)}`;
};

const porId = new Map(objetivos.filter((o) => esUuid(o.id)).map((o) => [o.id, o]));

return acciones
  .map((accion, indice) => {
    let tipo = texto(accion?.tipo, 60).toUpperCase();
    if (!tiposPermitidos.has(tipo)) return null;

    const datos = accion?.datos && typeof accion.datos === 'object' && !Array.isArray(accion.datos)
      ? accion.datos
      : {};

    let objetivoId = esUuid(datos.objetivo_id) && porId.has(datos.objetivo_id)
      ? datos.objetivo_id
      : '';

    if (!objetivoId && tipo !== 'CREAR_OBJETIVO') {
      const tituloBuscado = texto(datos.objetivo_titulo, 180).toLowerCase();
      const coincidencias = objetivos.filter((o) =>
        texto(o.titulo, 180).toLowerCase() === tituloBuscado
      );
      if (coincidencias.length === 1) objetivoId = coincidencias[0].id;
    }

    if (tipo !== 'CREAR_OBJETIVO' && !objetivoId) return null;

    const progreso = numero(datos.progreso);
    const valorActual = numero(datos.valor_actual);

    if (tipo === 'ACTUALIZAR_PROGRESO' && progreso === null && valorActual === null) {
      tipo = 'REGISTRAR_EVIDENCIA';
    }

    const hitos = Array.isArray(datos.hitos)
      ? datos.hitos.slice(0, 8).map((hito, orden) => {
          const titulo = texto(hito?.titulo, 180);
          return {
            clave: slug(hito?.clave || titulo || `hito_${orden + 1}`),
            titulo,
            descripcion: texto(hito?.descripcion, 500) || null,
            peso: Math.max(0.0001, numero(hito?.peso) ?? 1),
            orden: numero(hito?.orden) ?? orden,
            fecha_limite: fecha(hito?.fecha_limite),
          };
        }).filter((hito) => hito.titulo)
      : [];

    const payload = {
      titulo: texto(datos.titulo, 180) || null,
      descripcion: texto(datos.descripcion, 1200) || null,
      objetivo_titulo: texto(datos.objetivo_titulo, 180) || null,
      tipo_medicion: ['porcentaje', 'numerico', 'monetario', 'hitos'].includes(texto(datos.tipo_medicion).toLowerCase())
        ? texto(datos.tipo_medicion).toLowerCase()
        : null,
      valor_inicial: numero(datos.valor_inicial),
      valor_actual: valorActual,
      valor_objetivo: numero(datos.valor_objetivo),
      progreso,
      modo_valor: texto(datos.modo_valor).toLowerCase() === 'incremento' ? 'incremento' : 'absoluto',
      unidad: texto(datos.unidad, 80) || null,
      prioridad: Math.max(1, Math.min(5, numero(datos.prioridad) ?? 3)),
      criterio_exito: texto(datos.criterio_exito, 800) || null,
      proximo_paso: texto(datos.proximo_paso, 800) || null,
      fecha_inicio: fecha(datos.fecha_inicio),
      fecha_limite: fecha(datos.fecha_limite),
      estado: texto(datos.estado, 30).toLowerCase() || null,
      hito_clave: slug(datos.hito_clave) || null,
      hito_titulo: texto(datos.hito_titulo, 180) || null,
      hitos,
      evidencia: texto(datos.evidencia || i.mensaje, 1200),
      confianza: Math.max(0, Math.min(1, numero(datos.confianza) ?? 0.8)),
      metadata: {
        source_request_id: i.request_id || '',
        operacion: i.operacion || 'mensaje',
        extractor_version: 'eos-objectives-v2',
      },
    };

    const semilla = [
      i.request_id || i.mensaje || 'sin-request',
      tipo,
      objetivoId || payload.titulo || '',
      indice,
    ].join('|');

    return {
      json: {
        usuario_id: i.usuario_id,
        request_id_comando: uuidDeterminista(semilla),
        accion_objetivo: tipo,
        objetivo_id: objetivoId || null,
        payload_objetivo: payload,
        conversacion_id: esUuid(i.conversacion_id) ? i.conversacion_id : null,
        mensaje_id: esUuid(i.mensaje_id) ? i.mensaje_id : null,
      },
    };
  })
  .filter(Boolean);

const i = $input.first().json || {};
const text = (value, max = 2000) => String(value ?? '').trim().slice(0, max);
const isUuid = (value) => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text(value));
const hashHex = (value) => {
  let a = 0x811c9dc5;
  let b = 0x9e3779b9;
  for (const char of String(value)) {
    const code = char.charCodeAt(0);
    a = Math.imul(a ^ code, 0x01000193) >>> 0;
    b = Math.imul(b ^ (code + a), 0x85ebca6b) >>> 0;
  }
  const part = (number) => (number >>> 0).toString(16).padStart(8, '0');
  return (part(a) + part(b) + part(a ^ b) + part(Math.imul(a, b))).slice(0, 32);
};
const deterministicUuid = (seed) => {
  const hex = hashHex(seed).split('');
  hex[12] = '4';
  hex[16] = ['8', '9', 'a', 'b'][parseInt(hex[16], 16) % 4];
  const value = hex.join('');
  return `${value.slice(0, 8)}-${value.slice(8, 12)}-${value.slice(12, 16)}-${value.slice(16, 20)}-${value.slice(20, 32)}`;
};
const accion = text(i.accion_principal || i.accion || 'RESPONDER', 60).toUpperCase();
const requestId = isUuid(i.request_id)
  ? text(i.request_id)
  : deterministicUuid([i.usuario_id, i.conversacion_id, i.job_id, i.mensaje].join('|'));
const actionCommandId = deterministicUuid([i.usuario_id, requestId, accion].join('|'));
const inputFingerprint = hashHex(JSON.stringify({
  usuario_id: i.usuario_id,
  request_id: requestId,
  accion,
  mensaje: i.mensaje,
  datos_accion: i.datos_accion || {}
}));

return [{ json: {
  ...i,
  request_id: requestId,
  action_command_id: actionCommandId,
  action_started_epoch_ms: Date.now(),
  action_input_fingerprint: inputFingerprint,
  action_payload: {
    mensaje: text(i.mensaje),
    operacion: i.operacion || 'mensaje',
    datos_accion: i.datos_accion || {},
    acciones: Array.isArray(i.acciones) ? i.acciones.slice(0, 12) : [],
    parser_version: i.parser_version || ''
  }
} }];

const i = $('02 WK Preparar Orden Confiable').first().json || {};
return [{ json: {
  ok: true,
  duplicate: true,
  accion: i.accion_principal || 'RESPONDER',
  action_command_id: i.action_command_id,
