  action_event_type: tipoEvento,
  action_event_key: `terminal:${i.action_command_id}:1`,
  action_event_detail: detalle,
  action_error_code: noDisponible ? 'ACTION_NOT_AVAILABLE' : (tipoEvento === 'error' ? 'ACTION_EXECUTION_ERROR' : null),
  action_error_message: noDisponible
